import fs from 'node:fs';
import net from 'node:net';
import {createHash} from 'node:crypto';
const source="C:\\Users\\steven\\AppData\\Local\\Temp\\odin-native-diagnostic-99tq8mk4\\projects\\csharp_diagnostic\\Greeter.cs";const outside=["C:\\Users\\steven\\AppData\\Local\\Temp\\language-sandbox-v3-outside-yya13xw2\\outside-sentinel.txt", "E:\\odin\\.odin\\language-sandbox-v3-outside-j05vy6ta\\outside-sentinel.txt"];
const positive="C:\\Users\\steven\\AppData\\Local\\Temp\\odin-native-diagnostic-99tq8mk4\\backend-cache\\csharp_diagnostic\\native-positive-write.txt";const policy="C:\\Users\\steven\\AppData\\Local\\Temp\\odin-native-diagnostic-99tq8mk4\\policies\\fixed-policy.json";
const checks=[];const denied=(name,action)=>{try{action();checks.push({name,status:'FAIL'});}catch(error){checks.push({name,status:'PASS',error:error.code});}};
checks.push({name:'permitted_source_read',status:createHash('sha256').update(fs.readFileSync(source)).digest('hex')==="c511c991918b734eb5b97e4ccd8b81298568523ddf3e1e7d606558e7c51f3f1c"?'PASS':'FAIL'});
fs.writeFileSync(positive,'explicit-private-write');checks.push({name:'explicit_writable_positive',status:fs.readFileSync(positive,'utf8')==='explicit-private-write'?'PASS':'FAIL'});
for(const path of outside){const drive=path.slice(0,1);denied('outside_content_read_'+drive,()=>fs.readFileSync(path));denied('outside_overwrite_'+drive,()=>fs.writeFileSync(path,'denied'));}
denied('readonly_source_overwrite',()=>fs.writeFileSync(source,'denied'));
denied('readonly_source_create',()=>fs.writeFileSync(source+'.forbidden','denied'));
denied('protected_policy_read',()=>fs.readFileSync(policy));
for(const path of ["C:\\", "E:\\"]){checks.push({name:'volume_metadata_query_'+path.slice(0,1),status:fs.statSync(path).isDirectory()?'PASS':'FAIL'});}
const loopbackDenied=await new Promise(resolve=>{const socket=net.createConnection({host:'127.0.0.1',port:53125});socket.once('connect',()=>{socket.destroy();resolve(false);});socket.once('error',()=>resolve(true));socket.setTimeout(700,()=>{socket.destroy();resolve(true);});});
checks.push({name:'loopback_connection_denied',status:loopbackDenied?'PASS':'FAIL'});
console.log(JSON.stringify({checks}));process.exit(checks.every(c=>c.status==='PASS')?0:1);

